head.script:
scwin.screenId = "jldfil05035";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_nm", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "nm")); } },
        { childId: "ipt_telNo", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "telNo")); } },
        { childId: "ipt_faxNo", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "faxNo")); } },
        { childId: "ipt_email", fn: function () { return String(dlt_readDataVOArrayUser.getCellData(0, "email")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.ElwForm || { elements: [] });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05035.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil05035: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05035.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_ElwPageUsrSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ElwPageUsrSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.elwPageUsrSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05035.btn_ElwPageUsrSearch_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.elwPageUsrSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwPageUsrSearch = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwPageUsrSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form.bzCd.value   = BZ_USRLST ;

    if( scwin.form.isuNm != null ) {
        scwin.form.isuNm.value  = "" ;
    }

    scwin.form.action       = '/list/elwPage.do';
    scwin.form.method.value = 'elwPageSearch';
    await moveUrl('/list/elwPage.do', {});

    /* sdd-asis-lifecycle:end */
};
